-- Batch for Class 3 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C03-SCI-01', 3, '3-4', 'scientificInquiry', 'standard', 'A student puts an ice cube on a plate in the warm sun and another ice cube on a plate inside a refrigerator. After 10 minutes, the ice cube in the sun has completely melted into a puddle, while the ice in the refrigerator has barely changed. What is the cause of this difference?', '[{"text":"Thermal energy from the sun transferred heat to the ice, causing it to change state from solid to liquid faster.","correct":true},{"text":"The refrigerator creates new cold ice to replace what melted.","correct":false},{"text":"Sunlight absorbs water from the air and adds it to the plate.","correct":false},{"text":"Ice only melts when it is touched by moving air.","correct":false}]'::jsonb, 'States of matter and heat energy transfer causing phase changes.', 'Think about where the temperature is higher and heat is flowing into the ice.', 1.1, -1.8, 0.25, 'Singapore Primary 3 Science / US NGSS 2-PS1-4', true),
  ('C03-SCI-02', 3, '3-4', 'scientificInquiry', 'standard', 'A student tests which objects are attracted to a bar magnet. The magnet attracts an iron nail and a steel paperclip, but does not attract a copper penny, a plastic ruler, or an aluminum soda can. What conclusion can be drawn from this test?', '[{"text":"Only certain metals, such as iron and steel, exhibit magnetic attraction.","correct":true},{"text":"All shiny metal objects are strongly attracted to magnets.","correct":false},{"text":"The magnet was not strong enough to pick up the lighter objects.","correct":false},{"text":"Only objects shaped like thin rods can be attracted to magnets.","correct":false}]'::jsonb, 'Magnetic properties of materials and distinguishing ferromagnetic from non-magnetic metals.', 'Notice that copper and aluminum are metals, yet they did not stick to the magnet.', 1.2, -1.5, 0.25, 'Cambridge Primary Science Stage 3', true),
  ('C03-SCI-03', 3, '3-4', 'scientificInquiry', 'advanced', 'At 8:00 AM, a vertical pole casts a long shadow pointing west. At 12:00 noon, its shadow is very short and points north. At 4:00 PM, the shadow is long again and points east. What causes this continuous change in the shadow?', '[{"text":"Earth rotates on its axis, causing the sun to appear to move across the sky from east to west.","correct":true},{"text":"The sun physically grows larger and hotter during the middle of the day.","correct":false},{"text":"The pole bends as the temperature changes throughout the day.","correct":false},{"text":"Clouds push the sunlight in different directions as the wind blows.","correct":false}]'::jsonb, 'Sun position and shadow geometry caused by Earth rotation.', 'Shadows always fall in the direction opposite to where the light source is located.', 1.3, -1.1, 0.25, 'TIMSS Grade 4 Science / UK Key Stage 2', true),
  ('C03-SCI-04', 3, '3-4', 'scientificInquiry', 'advanced', 'A student places a dry sponge in a bowl with 100 mL of blue water. When the sponge is lifted out, only 30 mL of water remains in the bowl. The mass of the sponge increased by exactly 70 grams. What scientific principle does this demonstrate?', '[{"text":"Conservation of mass: the 70 mL of absorbed water was taken up by the porous sponge.","correct":true},{"text":"Water disappeared because the sponge destroyed liquid matter.","correct":false},{"text":"The blue dye evaporated instantly into the surrounding air.","correct":false},{"text":"The sponge grew heavier because water created new sponge fibers.","correct":false}]'::jsonb, 'Porosity, absorption, and mass conservation in physical mixtures.', 'Remember that 1 mL of water has a mass of approximately 1 gram.', 1.35, -0.8, 0.25, 'US NGSS 5-PS1-2 / Singapore Primary 3', true),
  ('C03-SCI-05', 3, '3-4', 'scientificInquiry', 'olympiad', 'A student drops three identical rubber balls from 1 meter height onto three surfaces: thick carpet, polished wood, and soft sand. The ball bounces 10 cm on carpet, 65 cm on wood, and 2 cm on sand. Why does the polished wood produce the highest bounce?', '[{"text":"The rigid wood deforms very little, returning most of the ball’s kinetic energy during the collision rather than absorbing it.","correct":true},{"text":"Wood possesses a natural magnetic charge that pushes rubber upward.","correct":false},{"text":"Soft sand adds gravity to the ball, preventing it from rising.","correct":false},{"text":"The carpet creates a vacuum that holds the ball down.","correct":false}]'::jsonb, 'Elastic collisions, energy dissipation, and surface rigidity.', 'Think about where the energy goes when an object hits a soft, shifting surface versus a hard one.', 1.5, -0.4, 0.25, 'SASMO Primary Science / Primary Olympiad', true),
  ('C03-SCI-06', 3, '3-4', 'scientificInquiry', 'olympiad', 'Two identical sealed glass jars contain water. Jar 1 is filled with cold ice water (4°C); Jar 2 is filled with warm water (40°C). After 5 minutes in a warm room, tiny water droplets form on the OUTSIDE of Jar 1, but the outside of Jar 2 stays completely dry. Where did the droplets on Jar 1 come from?', '[{"text":"Invisible water vapor in the surrounding air cooled and condensed into liquid when touching the cold glass.","correct":true},{"text":"Water leaked through tiny microscopic holes in the glass of Jar 1.","correct":false},{"text":"The cold glass produced water molecules from its own silica atoms.","correct":false},{"text":"The ice inside Jar 1 expanded so much that it pushed water outward.","correct":false}]'::jsonb, 'Atmospheric humidity, dew point, and condensation phase transition.', 'The jar is completely sealed, so the water must come from the air around it.', 1.6, 0, 0.25, 'Singapore Primary Science Olympiad', true),
  ('C03-CT-01', 3, '3-4', 'computationalThinking', 'standard', 'A robotic toy car starts at square (1, 1) on a grid facing North. It executes these instructions: [MOVE FORWARD 2, TURN RIGHT 90°, MOVE FORWARD 3]. At what grid position does the car stop?', '[{"text":"Square (4, 3)","correct":true},{"text":"Square (2, 3)","correct":false},{"text":"Square (3, 4)","correct":false},{"text":"Square (1, 5)","correct":false}]'::jsonb, 'Grid coordinates, directional heading, and sequential instruction execution.', 'Moving North increases the vertical coordinate; turning right makes it face East, increasing the horizontal coordinate.', 1.1, -1.7, 0.25, 'Bebras Computational Thinking Primary / Scratch Junior', true),
  ('C03-CT-02', 3, '3-4', 'computationalThinking', 'standard', 'Look at this repeating pattern of shapes: [Circle, Triangle, Square, Circle, Triangle, Square, Circle, Triangle, ...]. What shape will appear at the 15th position in this sequence?', '[{"text":"Square, because 15 is a multiple of 3 and Square is the 3rd shape in the repeating cycle.","correct":true},{"text":"Circle, because odd numbers always get circles.","correct":false},{"text":"Triangle, because it is in the middle of the pattern.","correct":false},{"text":"Star, because new shapes enter after position 10.","correct":false}]'::jsonb, 'Pattern recognition, modular repeating periods, and discrete arithmetic.', 'Divide the position number by the length of the repeating group (3 shapes).', 1.2, -1.4, 0.25, 'European Bebras Challenge Class 3', true),
  ('C03-CT-03', 3, '3-4', 'computationalThinking', 'advanced', 'A computer rule sorts fruit into baskets: "IF color is RED AND shape is ROUND, put in Basket 1; ELSE put in Basket 2." Where will a green round lime and a red long chili pepper be placed?', '[{"text":"Both the lime and the chili will go to Basket 2 because neither satisfies both conditions at once.","correct":true},{"text":"The lime goes to Basket 1 and the chili to Basket 2.","correct":false},{"text":"Both go to Basket 1 because each has at least one matching property.","correct":false},{"text":"The computer stops and reports an error.","correct":false}]'::jsonb, 'Boolean logical conjunction (AND) and conditional branch execution.', 'The word AND means both conditions must be true at the same time.', 1.35, -0.9, 0.25, 'Oxford University Computing Challenge (OUCC) Junior', true),
  ('C03-CT-04', 3, '3-4', 'computationalThinking', 'advanced', 'A baker has a loop program: [SET count = 0; REPEAT 4 TIMES: {ADD 3 cookies, SET count = count + 3}]. At the end of the loop, what is the final value of count?', '[{"text":"12 cookies","correct":true},{"text":"7 cookies","correct":false},{"text":"9 cookies","correct":false},{"text":"4 cookies","correct":false}]'::jsonb, 'Loop iteration, variable accumulation, and state tracing.', 'The loop runs 4 times, adding 3 each time: 3 + 3 + 3 + 3.', 1.4, -0.6, 0.25, 'Code.org Course B / CSTA K-2 Algorithms', true),
  ('C03-CT-05', 3, '3-4', 'computationalThinking', 'olympiad', 'A squirrel needs to cross a 4x4 stone pond. It can only hop RIGHT or UP. If stone (2, 2) is broken and cannot be stepped on, how many safe paths can the squirrel take from bottom-left (1, 1) to top-right (4, 4)?', '[{"text":"14 safe paths (total paths = 20; paths through (2, 2) = 2 × 3 = 6; 20 - 6 = 14).","correct":true},{"text":"20 safe paths","correct":false},{"text":"10 safe paths","correct":false},{"text":"16 safe paths","correct":false}]'::jsonb, 'Grid path enumeration with topological obstacles and combinatorial subtraction.', 'Count the total ways to navigate a 3-step by 3-step grid, then subtract the paths that pass through the broken stone.', 1.6, -0.1, 0.25, 'Australian Informatics Competition (AIC) Primary', true),
  ('C03-CT-06', 3, '3-4', 'computationalThinking', 'olympiad', 'Five children stand in line with heights: [120 cm, 135 cm, 110 cm, 140 cm, 125 cm]. An algorithm swaps adjacent neighbors that are in the wrong order until the line is sorted from shortest to tallest. What is the MINIMUM number of swaps needed?', '[{"text":"4 swaps (inversions count: (135,110), (120,110) doesn''t invert, (135,125), (140,125) etc.)","correct":true},{"text":"2 swaps","correct":false},{"text":"7 swaps","correct":false},{"text":"5 swaps","correct":false}]'::jsonb, 'Inversion counting and elementary bubble-sort swap metrics.', 'Count how many pairs of children have the taller child standing ahead of the shorter child.', 1.65, 0.2, 0.25, 'Bebras Castor Benjamin Olympiad', true),
  ('C03-ED-01', 3, '3-4', 'engineeringDesign', 'standard', 'Two children want to play on a playground seesaw. Child A weighs 30 kg and Child B weighs 15 kg. When Child A sits at the far end, Child B cannot push their side down. Where should Child A sit to balance the seesaw?', '[{"text":"Move closer to the center pivot (fulcrum), decreasing their turning force (torque).","correct":true},{"text":"Move further backward off the edge of the seat.","correct":false},{"text":"Wear heavier boots.","correct":false},{"text":"Stand up and jump continuously on the seat.","correct":false}]'::jsonb, 'First-class levers, fulcrum positioning, and rotational equilibrium.', 'To balance a lighter person, a heavier person needs to sit closer to the middle.', 1.15, -1.7, 0.25, 'US NGSS K-2-ETS1 / Singapore Primary 3', true),
  ('C03-ED-02', 3, '3-4', 'engineeringDesign', 'standard', 'A student builds a tall tower out of wooden blocks, but whenever someone bumps the table, the tower falls over immediately. Which modification will make the tower most stable?', '[{"text":"Widen the bottom base and place the heaviest blocks at the bottom to lower the center of gravity.","correct":true},{"text":"Make the tower narrower and twice as tall.","correct":false},{"text":"Put the heaviest blocks at the very top.","correct":false},{"text":"Paint the blocks with glossy paint.","correct":false}]'::jsonb, 'Structural stability, base-to-height ratio, and center of mass.', 'A pyramid is much harder to tip over than a tall, thin stick.', 1.25, -1.4, 0.25, 'Cambridge Primary Design & Technology', true),
  ('C03-ED-03', 3, '3-4', 'engineeringDesign', 'advanced', 'An engineer designs a ramp for rolling heavy boxes onto a truck bed that is 1 meter high. Ramp A is 2 meters long; Ramp B is 4 meters long. How does using Ramp B compare to Ramp A?', '[{"text":"Ramp B requires half as much pushing force, but the box must be pushed twice as far.","correct":true},{"text":"Ramp B requires twice as much pushing force because it is longer.","correct":false},{"text":"Both ramps require the exact same pushing force and distance.","correct":false},{"text":"Ramp B makes the box lighter on the scale.","correct":false}]'::jsonb, 'Inclined plane mechanical advantage and force-distance trade-off.', 'A gentler slope is easier to push up, but you have to walk further.', 1.4, -0.8, 0.25, 'Project Lead The Way (PLTW) Elementary', true),
  ('C03-ED-04', 3, '3-4', 'engineeringDesign', 'advanced', 'A team designs a handheld flashlight. They have a battery, a bulb, and insulated copper wires. When they connect wire from battery (+) to the bulb, the bulb does not light. What missing engineering requirement explains this?', '[{"text":"An electric circuit must be a complete closed loop returning to the battery (-) terminal for current to flow.","correct":true},{"text":"The bulb needs to be warmed up with a lighter first.","correct":false},{"text":"Electricity can only travel through glass tubes, not copper wires.","correct":false},{"text":"Batteries only produce power when placed upside down.","correct":false}]'::jsonb, 'Closed electrical circuit continuity and conductor pathway requirements.', 'Electricity must have a complete path to leave the battery and return to it.', 1.45, -0.5, 0.25, 'UK Key Stage 2 Science & Design', true),
  ('C03-ED-05', 3, '3-4', 'engineeringDesign', 'olympiad', 'To cross a 30 cm gap between two desks, students build a bridge using only one sheet of paper (20 cm × 30 cm) and 10 paper clips. A flat sheet immediately sags and collapses under its own weight. What folding technique gives paper the highest structural bending strength?', '[{"text":"Folding the paper into accordion pleats (corrugation), which increases the vertical depth of the cross-section.","correct":true},{"text":"Rolling the paper into a tight flat square.","correct":false},{"text":"Tearing the paper into thin confetti strips.","correct":false},{"text":"Soaking the paper in water before placing it.","correct":false}]'::jsonb, 'Corrugation, second moment of area, and structural geometry in thin materials.', 'Think about cardboard boxes: what is inside the walls of strong cardboard?', 1.6, -0.1, 0.25, 'FIRST LEGO League Junior Engineering Challenge', true),
  ('C03-ED-06', 3, '3-4', 'engineeringDesign', 'olympiad', 'A model water turbine uses falling water to spin a paddle wheel that lifts a small weight. If the water tank height is raised from 20 cm to 80 cm above the wheel, how does the gravitational potential energy of the falling water change?', '[{"text":"It quadruples (increases by a factor of 4), because potential energy is directly proportional to fall height ($PE = mgh$).","correct":true},{"text":"It doubles (increases by a factor of 2).","correct":false},{"text":"It remains unchanged because the volume of water is the same.","correct":false},{"text":"It decreases because water takes longer to reach the bottom.","correct":false}]'::jsonb, 'Gravitational potential energy scaling with height ($PE = mgh$).', '80 cm is 4 times higher than 20 cm.', 1.7, 0.2, 0.25, 'Singapore Primary Science & Engineering Challenge', true),
  ('C03-MR-01', 3, '3-4', 'mathematicalReasoning', 'standard', 'A school garden has a rectangular vegetable patch that is 6 meters long and 4 meters wide. The class wants to build a wooden border along all four sides. What is the total perimeter of the patch?', '[{"text":"20 meters ($6 + 4 + 6 + 4 = 20$ m)","correct":true},{"text":"24 meters ($6 \\times 4 = 24$ m)","correct":false},{"text":"10 meters ($6 + 4 = 10$ m)","correct":false},{"text":"16 meters","correct":false}]'::jsonb, 'Perimeter calculation of rectangles as sum of all four boundary sides.', 'Add the lengths of all four outer edges.', 1.1, -1.8, 0.25, 'Singapore Primary Math 3A / US Common Core 3.MD.D.8', true),
  ('C03-MR-02', 3, '3-4', 'mathematicalReasoning', 'standard', 'Maya baked 24 muffins. She gave 1/4 of them to her neighbor and divided the remaining muffins equally among 3 friends. How many muffins did each friend receive?', '[{"text":"6 muffins (24 - 6 = 18 remaining; 18 ÷ 3 = 6)","correct":true},{"text":"8 muffins","correct":false},{"text":"4 muffins","correct":false},{"text":"5 muffins","correct":false}]'::jsonb, 'Multi-step arithmetic combining unit fractions and equal sharing division.', 'First find 1/4 of 24, subtract that from 24, then divide what is left by 3.', 1.25, -1.3, 0.25, 'Kangaroo Math Benjamin Level / SASMO Grade 3', true),
  ('C03-MR-03', 3, '3-4', 'mathematicalReasoning', 'advanced', 'A clock shows 2:15 PM. If a train journey takes 2 hours and 50 minutes, what time will the train arrive at its destination?', '[{"text":"5:05 PM (2:15 + 2h = 4:15; 4:15 + 45m = 5:00; + 5m = 5:05 PM)","correct":true},{"text":"4:65 PM","correct":false},{"text":"5:15 PM","correct":false},{"text":"4:55 PM","correct":false}]'::jsonb, 'Elapsed time addition with sexagesimal (base-60) minute rollover.', 'There are 60 minutes in an hour, so adding 50 minutes to 15 minutes rolls past the next hour.', 1.35, -0.8, 0.25, 'TIMSS Grade 4 Mathematics', true),
  ('C03-MR-04', 3, '3-4', 'mathematicalReasoning', 'advanced', 'A mystery number has 3 digits: the hundreds digit is 4, the tens digit is double the hundreds digit, and the ones digit is 3 less than the tens digit. What is the mystery number?', '[{"text":"485 (Hundreds = 4, Tens = 8, Ones = 5)","correct":true},{"text":"425","correct":false},{"text":"488","correct":false},{"text":"463","correct":false}]'::jsonb, 'Place value decoding and relational deductive constraints.', 'Double of 4 is 8; 8 minus 3 is 5.', 1.45, -0.4, 0.25, 'Australian Mathematics Competition (AMC) Middle Primary', true),
  ('C03-MR-05', 3, '3-4', 'mathematicalReasoning', 'olympiad', 'In a farmyard there are chickens (2 legs each) and rabbits (4 legs each). Counting heads gives 10 heads; counting feet gives 28 feet. How many rabbits are in the farmyard?', '[{"text":"4 rabbits (and 6 chickens: 4 × 4 + 6 × 2 = 16 + 12 = 28 feet)","correct":true},{"text":"6 rabbits","correct":false},{"text":"5 rabbits","correct":false},{"text":"3 rabbits","correct":false}]'::jsonb, 'Simultaneous linear constraint problem solving via assumption heuristic.', 'If all 10 animals were chickens, there would only be 20 legs. Each rabbit adds 2 extra legs.', 1.6, 0, 0.25, 'SASMO Primary 3 / Singapore Heuristic Problem Solving', true),
  ('C03-MR-06', 3, '3-4', 'mathematicalReasoning', 'olympiad', 'How many triangles of any size are there in a large equilateral triangle divided into 4 small identical equilateral triangles by joining the midpoints of its three sides?', '[{"text":"5 triangles (4 small triangles + 1 large outer triangle)","correct":true},{"text":"4 triangles","correct":false},{"text":"6 triangles","correct":false},{"text":"8 triangles","correct":false}]'::jsonb, 'Systematic geometric shape enumeration and nested figure counting.', 'Count the small individual triangles first, and do not forget the large surrounding triangle.', 1.65, 0.3, 0.25, 'Kangaroo Math Ecolier / Bebras Junior', true),
  ('C03-ST-01', 3, '3-4', 'systemsThinking', 'standard', 'In a school garden ecosystem: Sunflowers provide seeds for sparrows, and sparrows are hunted by garden hawks. If a disease eliminates all the sparrows, what is the immediate expected effect on the hawks and the sunflowers?', '[{"text":"Hawks will face a food shortage, while sunflower seeds will accumulate with fewer birds eating them.","correct":true},{"text":"Hawks will immediately start eating sunflower leaves.","correct":false},{"text":"Sunflowers will stop growing flowers entirely.","correct":false},{"text":"All organisms in the garden will double within one day.","correct":false}]'::jsonb, 'Linear trophic cascade and primary consumer disruption in simple food chains.', 'Trace who eats whom: if the middle animal vanishes, what happens to the predator and the food source?', 1.15, -1.7, 0.25, 'UNESCO Primary Science Indicators / OECD PISA Primary', true),
  ('C03-ST-02', 3, '3-4', 'systemsThinking', 'standard', 'On a sunny day after rain, a large puddle on asphalt disappears by afternoon even though no drain exists. Where did the water in the puddle go?', '[{"text":"The liquid water absorbed heat energy and evaporated into invisible water vapor gas in the atmosphere.","correct":true},{"text":"The asphalt soaked up all the water and turned into a solid sponge.","correct":false},{"text":"Car tires drank the water to stay cool.","correct":false},{"text":"The water was destroyed by sunlight.","correct":false}]'::jsonb, 'Hydrological cycle phase change and atmospheric water reservoir transfer.', 'Water does not disappear from the universe; it changes into an invisible gas in the air.', 1.25, -1.4, 0.25, 'TIMSS Grade 4 Earth Science', true),
  ('C03-ST-03', 3, '3-4', 'systemsThinking', 'advanced', 'A classroom has an aquarium with fish and live green plants. If the teacher moves the aquarium into a completely dark room for two weeks, why do the fish begin to struggle for breath even though they have food?', '[{"text":"Without sunlight, plants cannot perform photosynthesis to produce dissolved oxygen for the fish to breathe.","correct":true},{"text":"Fish are afraid of the dark and stop swimming.","correct":false},{"text":"Water freezes solid in darkness within hours.","correct":false},{"text":"Fish food only dissolves when bright light shines on it.","correct":false}]'::jsonb, 'Interdependent closed-loop gas exchange (O2 and CO2) in aquatic ecosystems.', 'Plants need light to make oxygen for fish to breathe underwater.', 1.35, -0.8, 0.25, 'US NGSS 5-LS2-1 Ecosystem Interdependence', true),
  ('C03-ST-04', 3, '3-4', 'systemsThinking', 'advanced', 'A town builds a new asphalt parking lot where a grassy meadow used to be. During the next heavy thunderstorm, the street next to the parking lot floods severely. Why did replacing grass with asphalt cause flooding?', '[{"text":"Grass and soil absorb and slow down rainwater infiltration, whereas impermeable asphalt forces all rainwater to rush immediately into the street.","correct":true},{"text":"Asphalt attracts more rain clouds from the sky.","correct":false},{"text":"Cars parked on the lot push water upward with their tires.","correct":false},{"text":"Asphalt melts in rainwater, blocking storm pipes.","correct":false}]'::jsonb, 'Surface permeability, storm runoff kinetics, and human-altered urban drainage systems.', 'Water can soak into dirt and grass, but it rolls straight off smooth pavement.', 1.45, -0.4, 0.25, 'OECD PISA Environmental Systems / UNESCO SDG 11', true),
  ('C03-ST-05', 3, '3-4', 'systemsThinking', 'olympiad', 'A honeybee visits flowers to collect nectar, and pollen grains stick to its fuzzy body and transfer to the next flower. Both the bee and the flowering plant benefit. What systemic ecological relationship is this?', '[{"text":"Mutualism: a symbiotic co-dependent feedback loop where both species enhance each other’s survival and reproduction.","correct":true},{"text":"Parasitism: where the bee steals resources and damages the flower.","correct":false},{"text":"Predation: where the flower captures and digests the bee.","correct":false},{"text":"Competition: where the bee and flower fight for the same sunlight.","correct":false}]'::jsonb, 'Symbiotic mutualism, plant-pollinator co-evolution, and positive ecological feedback.', 'Both living things gain something essential: food for the bee, reproduction for the plant.', 1.6, 0.1, 0.25, 'Singapore Primary Science Olympiad / SASMO Junior', true),
  ('C03-ST-06', 3, '3-4', 'systemsThinking', 'olympiad', 'In a mechanical grandfather clock, a falling weight pulls a chain that turns gear wheels, but an escapement mechanism allows the gears to turn only one tooth every second with a swinging pendulum. What is the function of the escapement in this system?', '[{"text":"It acts as a feedback governor, regulating the release of stored potential energy into precise, constant time intervals.","correct":true},{"text":"It winds the clock weight back up to the top automatically.","correct":false},{"text":"It stops the clock from making ticking sounds.","correct":false},{"text":"It creates electricity to power digital numbers.","correct":false}]'::jsonb, 'Systemic energy regulation, escapement governance, and clockwork mechanical feedback.', 'Without this part, the weight would fall to the floor in one second and spin the hands wildly.', 1.65, 0.35, 0.25, 'Cambridge Primary STEM / ISEC Systems Design', true);
